hub=f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>برندهای قابل سورسینگ تجهیزات صنعتی | پیشرو تجهیز فرتاک</title><meta name="description" content="هاب برندهای قابل بررسی برای سورسینگ تجهیزات صنعتی؛ بدون ادعای نمایندگی رسمی، با تمرکز بر Part Number، وندورلیست و مدارک قابل ردیابی."><meta name="robots" content="index, follow"><link rel="canonical" href="{BASE}brands/"><link rel="alternate" hreflang="fa-IR" href="{BASE}brands/"><link rel="alternate" hreflang="x-default" href="{BASE}brands/"><link rel="stylesheet" href="../assets/css/style.css"><script type="application/ld+json">{json.dumps(hub_schema,ensure_ascii=False)}</script><style>body{{background:#f8fafc}}.hero{{padding:130px 0 50px;background:#0f2744;color:#fff}}.hero h1{{color:#fff}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px;margin:28px auto 70px}}.brand-card{{display:grid;gap:8px;background:#fff;border:1px solid #e2e8f0;border-radius:22px;padding:20px;text-decoration:none;color:#0f2744}}.brand-card span{{color:#ef4b1a;font-weight:900}}.brand-card small{{color:#64748b;line-height:1.8}}</style></head><body><header class="site-header scrolled"><div class="container nav-wrap"><a class="brand" href="../"><img width="54" height="54" loading="lazy" src="../assets/images/ptf-logo.png" alt="لوگو"><span><b>پیشرو تجهیز فرتاک</b></span></a><nav class="main-nav"><a href="../">خانه</a><a href="../services/products/">محصولات</a><a href="../rfq/">RFQ</a></nav></div></header><section class="hero"><div class="container"><h1>برندهای قابل سورسینگ تجهیزات صنعتی</h1><p>این بخش برای تقویت سئوی برندمحور و شفاف‌سازی معیارهای خرید برندها ایجاد شده است. هیچ صفحه‌ای ادعای نمایندگی رسمی ندارد؛ هر سفارش باید با وندورلیست و مدارک پروژه کنترل شود.</p></div></section><main class="container grid">{cards}</main><script src="../assets/js/ptf-metrics.js" defer></script></body></html>'''
OUT.mkdir(exist_ok=True)
(OUT/'index.html').write_text(hub,encoding='utf-8')
for b in BRANDS:
 (OUT/(b['slug']+'.html')).write_text(page(b),encoding='utf-8')
